<?php $title="Departments & Classes";require "../includes/header.php";if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM departments WHERE id=?")->execute([(int)$_GET['delete']]);header("Location:index.php");exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO departments(name) VALUES(?)")->execute([trim($_POST['name'])]);header("Location:index.php");exit;}$ds=$pdo->query("SELECT d.*,COUNT(s.id) students FROM departments d LEFT JOIN students s ON s.department_id=d.id GROUP BY d.id ORDER BY d.name")->fetchAll();?><div class="row g-3"><div class="col-md-4"><div class="card p-4"><h5>Add Department/Class</h5><form method="post"><input name="name" class="form-control mb-2" placeholder="e.g. Computer Science & Technology" required><button class="btn btn-primary">Add</button></form></div></div><div class="col-md-8"><div class="card p-3"><h5>Department List</h5><table class="table"><tr><th>Name</th><th>Students</th><th>Action</th></tr><?php foreach($ds as $d):?><tr><td><?=htmlspecialchars($d['name'])?></td><td><?=$d['students']?></td><td><a data-confirm="Delete department?" class="btn btn-sm btn-outline-danger" href="?delete=<?=$d['id']?>">Delete</a></td></tr><?php endforeach;?></table></div></div></div><?php require "../includes/footer.php";?>